test:
// magic-patch — comfyui-kjnodes / web/js/utility.js
// rule: converted-widget-protocol (line 37)
//
// Run this file against BOTH the original and the converted source.
//
//   equivalence  must pass on both — the conversion changed no behaviour
//   fix          must FAIL on the original and PASS on the converted source
//
// `hideWidgetForGood` hid a widget by overwriting `widget.type` with
// "converted-widget" and stubbing `computeSize` to [0, -4].
//
// The serialization coupling the reference warns about is ABSENT here. The
// easy-use variant of this helper installs a `serializeValue` that returns
// undefined unless the matching input is linked; this pack's variant saves
// `origSerializeValue` and never overwrites `serializeValue`. And
// `LGraphNode.serialize` skips a widget only on `serialize === false` — it
// never consults `type`. So hiding was presentation-only before, `hidden` is
// presentation-only after, and `widgets_values` is untouched either way. That
// is what the equivalence half pins.
import { createPinia, setActivePinia } from 'pinia'
import { beforeAll, beforeEach, describe, expect, it } from 'vitest'

import { LGraph } from '@/lib/litegraph/src/LGraph'
import { LGraphNode } from '@/lib/litegraph/src/LGraphNode'
import type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'
import { resetComfyApi, useComfyApi } from '@/platform/nodeApi/comfyApi'

/** The file under test: the original for the red run, the converted for green. */
const UNDER_TEST =
  process.env.KJNODES_UTILITY ?? 'ComfyUI-KJNodes-HEAD/web/js/utility.js'

let graph: LGraph
let node: LGraphNode
let hideWidgetForGood: (node: LGraphNode, widget: IBaseWidget) => void

beforeAll(async () => {
  setActivePinia(createPinia())
  resetComfyApi()
  // The module reads `window.comfyAPI.app` at load and the converted source
  // destructures `window.comfy` at module scope, so both must exist before the
  // import — and the API instance must keep resolving whichever graph a test
  // builds, hence the getter closing over `graph`.
  window.comfyAPI = { app: { app: {} } }
  window.comfy = useComfyApi(() => graph)
  ;({ hideWidgetForGood } = (await import(/* @vite-ignore */ UNDER_TEST)) as {
    hideWidgetForGood: (node: LGraphNode, widget: IBaseWidget) => void
  })
})

beforeEach(() => {
  graph = new LGraph()
  node = new LGraphNode('Sampler')
  graph.add(node)
  node.serialize_widgets = true
  node.addWidget('number', 'seed', 123, () => {})
  node.addWidget('combo', 'control_after_generate', 'randomize', () => {}, {
    values: ['fixed', 'randomize']
  })
  // seed + its control widget: the linkedWidgets pair the helper recurses over.
  node.widgets![0].linkedWidgets = [node.widgets![1]]
})

describe('comfyui-kjnodes hideWidgetForGood', () => {
  describe('equivalence — must pass before and after', () => {
    it('leaves the widget values untouched', () => {
      hideWidgetForGood(node, node.widgets![0])

      expect(node.widgets![0].value).toBe(123)
      expect(node.widgets![1].value).toBe('randomize')
    })

    it('does not change what the node serializes', () => {
      const before = JSON.stringify(node.serialize().widgets_values)

      hideWidgetForGood(node, node.widgets![0])

      expect(before).toBe(JSON.stringify([123, 'randomize']))
      expect(JSON.stringify(node.serialize().widgets_values)).toBe(before)
    })

    it('keeps widget array membership and order', () => {
      hideWidgetForGood(node, node.widgets![0])

      expect(node.widgets!.map((w) => w.name)).toEqual([
        'seed',
        'control_after_generate'
      ])
    })
  })

  describe('fix — must fail before, pass after', () => {
    it('makes the widget invisible', () => {
      hideWidgetForGood(node, node.widgets![0])

      // The old hack renamed the type; nothing in litegraph reads
      // 'converted-widget', so the widget stayed visible and full-height.
      expect(node.isWidgetVisible(node.widgets![0])).toBe(false)
    })

    it('hides linked widgets too', () => {
      hideWidgetForGood(node, node.widgets![0])

      expect(node.isWidgetVisible(node.widgets![1])).toBe(false)
    })

    it('leaves widget type identity intact', () => {
      hideWidgetForGood(node, node.widgets![0])

      expect(node.widgets![0].type).toBe('number')
      expect(node.widgets![1].type).toBe('combo')
    })
  })
})
